import{_ as e,c as t,o as s,af as p}from"./chunks/framework.BKeRpnBD.js";const f=JSON.parse('{"title":"关于子夏传真伪","description":"子夏易传 - 关于子夏传真伪","frontmatter":{"title":"关于子夏传真伪","description":"子夏易传 - 关于子夏传真伪"},"headers":[],"relativePath":"zh/classics/zixia/001.md","filePath":"zh/classics/zixia/001.md"}'),i={name:"zh/classics/zixia/001.md"};function r(c,a,_,o,n,l){return s(),t("div",null,[...a[0]||(a[0]=[p('<h1 id="关于子夏传真伪" tabindex="-1">关于子夏传真伪 <a class="header-anchor" href="#关于子夏传真伪" aria-label="Permalink to “关于子夏传真伪”">​</a></h1><p>注意</p><p>《子夏易传》实为伪作，现今的《子夏易传》不仅非子夏所撰，也并非完全为张弧所撰，而是出自众家之手。但其内容却具有一定的参考价值。它孕含了较多汉唐时期的《易》学思想，对于研究、探讨《周易》古义有着不可替代的作用。</p><p>《子夏易传》，一部被现代易学界认定为伪书的易学古籍，书称作者卜子夏。《子夏易传》一为二卷，一为十一卷。旧本题卜子夏（前 507 一？）所撰。</p><p>序：子夏姓卜名商，春秋末晋国温（今河南温县）人，孔子的学生，为莒父宰。孔子死后，到魏国讲学，主张国君要学习《春秋》，吸取历史教训，宣扬“死生有命，富贵在天”等观点，李克、吴起都是其弟子，魏文侯也尊以为师，相传《诗》、《春秋》等儒家经典就是由他传授下来的。学术界历来主张，此书为后人伪撰，而托附于子夏名下，《四库全书总目》认为“其伪中生伪，至一至再而未已者，亦莫若是书”。</p><p>《隋书·经籍志》所著录的二卷本，其实是魏晋间大兴《易》学之风时为当时人所伪撰而流布于世。据《唐会要》载：“开元七年诏”，当时因《子夏易传》无传习者，遂令儒官详定，刘知已认为，此书不见于《汉书·艺文志》，至梁阮孝绪《七录》始有著录，作六卷，或云韩婴作，或云丁宽作，而至为可疑。司马贞认为，刘向《七略》有《子夏易传》，但其书久佚，晋荀勖《中经簿》有《子夏易传》四卷，或云丁宽，是其已怀疑非子夏所撰。因此，唐玄宗采纳了刘、司马氏的建议，而停止向学校颁行。代宗以年，此本亡佚。</p><p>清马国翰《玉函山房辑佚书》中有辑佚本。今所传十一卷本，始为晁说之《传易堂记》所著录，其称“今称《子夏传》者，乃唐张弧之《易》。据此，则今本应是张弧伪撰。弧为唐末人，曾官大理寺评事。其书以王弼《周易注》为底本而说以义理，所说义理，大致上以儒家“王道”的社会政治思想与《周易》经文相附会。</p><p>迨朱彝尊作《经义考》，证以陆德明《经典释文》、李鼎祚《周易集解》及王应麟《困学纪闻》所引诸条目，则于今本全无，知张弧伪撰之书又遭后人增削伪纂，并又多衍出一卷，为十一卷。因此，今本《于夏易传》不但不是子夏所撰，亦并非完全为张弧所撰，云其出自众家之手，可谓不诬。</p><p>二本虽为伪造，但其内容却有—定的参考价值，孕含了较多汉唐时期的《易》学思想，《四库全书总目》云“案说《易》之家，最古者莫若是书”，故其对研究、探讨《周易》古义，二本参稽，仍为它书所不可替代。二卷本除为马国翰所辑外，《汉学堂丛书·经解·逸书考》中亦有考辑。今本则有《四库全书》本，《通志堂经解》本及《学津讨原》本等。</p>',9)])])}const h=e(i,[["render",r]]);export{f as __pageData,h as default};
